import React from 'react';
import { Select } from 'antd';
import { sources } from './data/sources';
import './SourcesExcludedInput.css';

const SourcesExcludedInput = ({ value = [], onChange }) => {
  // Convert sources array to options format for Select
  const sourceOptions = sources.map(source => ({
    value: source.codename,
    label: (
      <div className="source-option">
        <div className="source-option-content">
          <img 
            src={`/${source.iata}.png`}
            alt={source.airline}
            className="airline-logo"
            onError={(e) => {
              e.target.src = '/default.png';
            }}
          />
          <div className="source-details">
            <div className="airline-name">{source.airline}</div>
            <div className="program-name">{source.ffname}</div>
          </div>
        </div>
        <div className="source-code">{source.iata}</div>
      </div>
    ),
    data: source // Store full source data for reference
  }));

  const handleChange = (selectedValues) => {
    onChange?.(selectedValues);
  };

  // Custom filter function to match AC Route Builder behavior
  const filterOption = (input, option) => {
    if (!input) return true;
    const source = option.data;
    if (!source) return false;

    const searchText = input.toUpperCase();
    const iata = source.iata;

    // Exact IATA match gets highest priority
    if (iata === searchText) return true;

    // Then IATA starts with search text
    if (iata.startsWith(searchText)) return true;

    // Then airline name starts with search text
    if (source.airline.toUpperCase().startsWith(searchText)) return true;

    // Then program name starts with search text
    if (source.ffname.toUpperCase().startsWith(searchText)) return true;

    // Finally, check if any field contains the search text
    return (
      source.airline.toUpperCase().includes(searchText) ||
      source.ffname.toUpperCase().includes(searchText)
    );
  };

  // Custom sort function to match AC Route Builder behavior
  const sortOptions = (optionA, optionB, inputValue) => {
    if (!inputValue) return 0;

    const searchText = String(inputValue).toUpperCase();
    const sourceA = optionA.data;
    const sourceB = optionB.data;

    // Helper function to get sort score (higher = better match)
    const getScore = (source) => {
      const iata = source.iata;
      if (iata === searchText) return 100;
      if (iata.startsWith(searchText)) return 90;
      if (source.airline.toUpperCase().startsWith(searchText)) return 80;
      if (source.ffname.toUpperCase().startsWith(searchText)) return 70;
      if (iata.includes(searchText)) return 60;
      if (source.airline.toUpperCase().includes(searchText)) return 50;
      if (source.ffname.toUpperCase().includes(searchText)) return 40;
      return 0;
    };

    const scoreA = getScore(sourceA);
    const scoreB = getScore(sourceB);

    if (scoreA !== scoreB) return scoreB - scoreA;
    return sourceA.airline.localeCompare(sourceB.airline);
  };

  return (
    <Select
      mode="multiple"
      allowClear
      style={{ width: '100%' }}
      placeholder="Select airlines to exclude"
      value={value}
      onChange={handleChange}
      options={sourceOptions}
      filterOption={filterOption}
      filterSort={sortOptions}
      optionFilterProp="children"
      listHeight={320}
      menuItemSelectedIcon={null}
      className="sources-excluded-select"
    />
  );
};

export default SourcesExcludedInput;
